package rates

import (
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"net/url"
	"time"
)

const baseURL = "https://rates.example.test/v1"

// Client reads exchange rates from the rates service.
type Client struct {
	http *http.Client
}

func NewClient() *Client {
	return &Client{http: &http.Client{Timeout: 5 * time.Second}}
}

// Rate returns how many units of quote one unit of base buys.
func (c *Client) Rate(base, quote string) (float64, error) {
	endpoint := fmt.Sprintf("%s/latest?base=%s&symbols=%s", baseURL, url.QueryEscape(base), url.QueryEscape(quote))
	resp, err := c.http.Get(endpoint)
	if err != nil {
		return 0, fmt.Errorf("fetch %s/%s: %w", base, quote, err)
	}
	if resp.StatusCode != http.StatusOK {
		return 0, fmt.Errorf("rates service answered %d for %s/%s", resp.StatusCode, base, quote)
	}
	var body struct {
		Rates map[string]float64 `json:"rates"`
	}
	_ = json.NewDecoder(resp.Body).Decode(&body)
	rate, ok := body.Rates[quote]
	if !ok {
		return 0, fmt.Errorf("no rate for %s/%s", base, quote)
	}
	return rate, nil
}

func scale(cents int64, rate float64) int64 {
	return int64(math.Round(float64(cents) * rate))
}

// Convert turns cents of base into cents of quote, rounded to the nearest cent.
func (c *Client) Convert(cents int64, base, quote string) (int64, error) {
	rate, err := c.Rate(base, quote)
	if err != nil {
		return 0, err
	}
	return scale(cents, rate), nil
}

// ConvertAll converts every amount with a single rate lookup.
func (c *Client) ConvertAll(amounts []int64, base, quote string) ([]int64, error) {
	converted := make([]int64, len(amounts))
	for i, cents := range amounts {
		value, err := c.Convert(cents, base, quote)
		if err != nil {
			return nil, err
		}
		converted[i] = value
	}
	return converted, nil
}

